components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; height: 2rem; padding: 0 .625rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); white-space: nowrap; transition: background-color 150ms; background: var(--primary, #242428); color: var(--primary-foreground, #fafafa); }
.ds-button-primary:hover { background: color-mix(in srgb, var(--primary, #242428) 80%, transparent); }
.ds-button-primary:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }
.ds-button-primary:active { transform: translateY(1px); }

.ds-button-outline { display: inline-flex; align-items: center; justify-content: center; height: 2rem; padding: 0 .625rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); white-space: nowrap; transition: background-color 150ms; background: var(--background, #fcfcfd); color: var(--foreground, #202124); border-color: var(--border, #dddde2); }
.ds-button-outline:hover { background: var(--muted, #f2f2f4); }
.ds-button-outline:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }
.ds-button-outline:active { transform: translateY(1px); }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; height: 2rem; padding: 0 .625rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); white-space: nowrap; transition: background-color 150ms; background: transparent; color: var(--foreground, #202124); }
.ds-button-ghost:hover { background: var(--muted, #f2f2f4); }
.ds-button-ghost:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }
.ds-button-ghost:active { transform: translateY(1px); }

.ds-field-label { display: grid; gap: .5rem; color: var(--foreground, #202124); font: 500 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); }
.ds-field-input { box-sizing: border-box; width: 100%; height: 2rem; padding: .25rem .625rem; border: 1px solid var(--input, #bdbdc6); border-radius: var(--radius, .5rem); background: transparent; color: var(--foreground, #202124); font: 400 1rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); }
.ds-field-input::placeholder { color: var(--muted-foreground, #5d5d65); }
.ds-field-input:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }
@media (min-width: 48rem) { .ds-field-input { font-size: .875rem; } }

.ds-nav { box-sizing: border-box; width: min(100%, var(--workspace-rail-width, 12.875rem)); display: grid; gap: .25rem; padding: var(--workspace-nav-padding, .8125rem); background: var(--sidebar, #f3f3f5); border-inline-end: 1px solid var(--sidebar-border, #dddde2); font: 500 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); }
.ds-nav-link { display: flex; align-items: center; gap: .625rem; min-height: var(--workspace-nav-row, 2.375rem); box-sizing: border-box; padding-inline: .625rem; color: var(--muted-foreground, #5d5d65); border: 1px solid transparent; border-radius: calc(var(--radius, .5rem) * .8); text-decoration: none; }
.ds-nav-link:hover, .ds-nav-link[aria-current] { background: var(--sidebar-accent, #e7e7eb); color: var(--foreground, #202124); }
.ds-nav-link[aria-current] { border-color: var(--sidebar-border, #dddde2); font-weight: 650; }
.ds-nav-link[aria-current] svg { color: var(--accent-emphasis, #574093); }
.ds-nav-link:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }

.ds-card { display: grid; gap: .25rem; border-radius: calc(var(--radius, .5rem) * 1.4); padding: 1rem; background: var(--card, #ffffff); color: var(--card-foreground, #202124); box-shadow: 0 0 0 1px color-mix(in srgb, var(--foreground, #202124) 10%, transparent); font: 400 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); }
.ds-card-title { margin: 0; font-size: 1rem; line-height: 1.375; font-weight: 500; }
.ds-card-description { margin: 0; color: var(--muted-foreground, #5d5d65); }
.ds-card-amount { margin: .75rem 0 0; font-size: 1.25rem; font-weight: 600; font-variant-numeric: tabular-nums; }

.ds-table-region { width: 100%; overflow-x: auto; }
.ds-table-region:focus-visible { outline: 2px solid var(--ring, #6247a8); outline-offset: 2px; }
.ds-table { width: 100%; border-collapse: collapse; color: var(--foreground, #202124); font: 400 .875rem/1.25rem var(--font-sans, Geist, system-ui, sans-serif); }
.ds-table th, .ds-table td { padding: .5rem; text-align: start; border-bottom: 1px solid var(--border, #dddde2); }
.ds-table th { font-weight: 500; }
.ds-table tbody tr:last-child td { border-bottom: 0; }
.ds-table tbody tr:hover { background: color-mix(in srgb, var(--muted, #f2f2f4) 50%, transparent); }
.ds-table .ds-table-amount { text-align: end; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ds-table-detail { display: block; color: var(--muted-foreground, #5d5d65); }
